<?php $e = static fn (mixed $v): string => App\Core\View::e($v); ?>
<section class="page-stack"><div class="section-heading"><div><p class="eyebrow">Operação de partida</p><h1>Minhas partidas</h1><p class="muted">Somente partidas atribuídas a você. Registre fatos; a homologacao atualiza os dados do campeonato.</p></div></div>
<?php if ($items === []): ?><article class="panel empty-state"><h2>Nenhuma partida atribuída</h2><p>O organizador ainda não atribuiu uma partida ao seu usuário.</p></article><?php else: ?><div class="match-grid"><?php foreach ($items as $item): ?><article class="panel match-card"><p class="eyebrow"><?= $e($item['championship_name']) ?> · Rodada <?= (int) $item['round_number'] ?></p><h2><?= $e($item['home_team_name']) ?> <span>x</span> <?= $e($item['away_team_name']) ?></h2><p><?= $e($item['match_date'] ?: 'Data a definir') ?> <?= $e(substr((string) $item['match_time'], 0, 5)) ?> · <?= $e($item['venue_name'] ?: 'Local a definir') ?></p><div class="action-nav"><a class="button" href="<?= $e(App\Core\Config::url('/admin/partidas/' . $item['id'] . '/operacao')) ?>">Abrir central</a><a class="button secondary" href="<?= $e(App\Core\Config::url('/admin/partidas/' . $item['id'] . '/evidencias')) ?>">Evidências</a></div></article><?php endforeach; ?></div><?php endif; ?></section>
